/* ==========================================================
   MoodTube theme: Field Recorder  (theme format v2)
   Light-grey handheld recorder: black bezel, waveform strip with a
   red playhead, dark LCD with the cover and the big timer, round
   neumorphic buttons, smooth volume slider with a round knob.
   Waveform art is inlined by the build script (placeholder below).
   ========================================================== */

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&display=swap');

@keyframes rc-blink { 50% { opacity: 0.3; } }

/* ---------- Palette ---------- */
.mt-player, #mt-settings-modal, .mt-fab, .mt-pl-modal {
    --rc-body:  #f1f1f1;
    --rc-panel: #e7e7e7;
    --rc-edge:  #cfcfcf;
    --rc-ink:   #1c1c1c;
    --rc-dim:   #8a8a8a;
    --rc-red:   #c8423f;
    --rc-black: #111111;
    --mt-text: var(--rc-ink);
    --mt-text-dim: var(--rc-dim);
    --mt-text-on-accent: #ffffff;
}

