    --mt-slider-thumb-bg-hover: linear-gradient(#ffffff, #efefef);
    --mt-slider-thumb-border: 1px solid #bdbdbd;
    --mt-slider-thumb-radius: 50%;
    --mt-slider-thumb-shadow: 0 1px 1px rgba(0, 0, 0, 0.15);
