/* ---------- Body ---------- */
.mt-player {
    padding: 30px 12px 12px;
    background: var(--rc-body);
    border: 4px solid var(--rc-black);
    border-radius: 24px;
    color: var(--rc-ink);
    font-family: 'Inter', 'Segoe UI', sans-serif;
    box-shadow: none;
    backdrop-filter: none; -webkit-backdrop-filter: none;
}
.mt-player * { font-family: inherit; }
.mt-player i { font-family: 'Font Awesome 6 Free', 'Font Awesome 5 Free', FontAwesome; }

/* Title strip: the header is flattened so label and status can sit anywhere */
.mt-player:not(.moodtube-row-layout) .mt-player-header { display: contents; }
.mt-player-header-title {
    color: var(--rc-dim); font-size: 10px; font-weight: 600; letter-spacing: 0.14em; text-transform: uppercase;
}
.mt-player:not(.moodtube-row-layout) .mt-player-header-title { position: absolute; top: 11px; left: 16px; z-index: 6; }

.mt-window-btn {
    top: 6px; width: 18px; height: 18px; box-sizing: border-box;
    display: flex; align-items: center; justify-content: center;
    font-size: 8px; color: var(--rc-dim);
    background: linear-gradient(#fcfcfc, #e9e9e9); border: 1px solid var(--rc-edge); border-radius: 50%;
}
.mt-btn-search   { right: 58px; }
.mt-btn-settings { right: 34px; }
.mt-btn-close    { right: 10px; }

.mt-player-body { gap: 8px; justify-content: flex-start; }

/* ---------- Waveform strip (progress) ---------- */
.mt-player:not(.moodtube-row-layout) .mt-progress {
    order: 1; width: calc(100% + 24px); margin: 0 -12px; height: 52px; box-sizing: border-box;
    border-top: 1px solid var(--rc-edge); border-bottom: 1px solid var(--rc-edge);
    display: flex; align-items: center;
}
/* both timers move onto the LCD */
.mt-player:not(.moodtube-row-layout) .mt-time { position: absolute; z-index: 3; pointer-events: none; }
.mt-player:not(.moodtube-row-layout) .mt-time-current { right: 10px; top: 112px; font-size: 30px; font-weight: 500; color: #f2f2f2; letter-spacing: -0.02em; }
.mt-player:not(.moodtube-row-layout) .mt-time-total   { right: 10px; top: 68px;  font-size: 11px; color: #9a9a9a; }
.mt-time { color: var(--rc-dim); font-size: 10px; }

/* ---------- LCD (cover) ---------- */
.mt-player:not(.moodtube-row-layout) .mt-cover {
    order: 2; width: 100%; height: 92px; box-sizing: border-box; padding: 10px;
    justify-content: flex-start; align-items: flex-end;
    border: none; border-radius: 12px; box-shadow: none;
    background: linear-gradient(112deg, #2d2d2d 0 46%, #1b1b1b 46%);
}
.mt-player:not(.moodtube-row-layout) .mt-cover-img {
    width: 54px; height: 54px; flex: none; border-radius: 8px; object-fit: cover; background: #3a3a3a;
}
.mt-player:not(.moodtube-row-layout) .mt-cover-hole { display: none; }

/* status badge sits on the LCD, like the REC badge on the reference */
.mt-player-status { color: var(--rc-ink); opacity: 1; }
.mt-player:not(.moodtube-row-layout) .mt-player-status {
    position: absolute; z-index: 3; top: 98px; left: 22px;
    display: inline-flex; align-items: center; padding: 2px 8px 2px 7px;
    background: #f2f2f2; border-radius: 8px;
    font-size: 10px; font-weight: 600; letter-spacing: 0.08em;
}
.mt-player-status:empty { display: none; }
.mt-player-status::before { content: ''; width: 6px; height: 6px; margin-right: 5px; border-radius: 50%; background: var(--rc-ink); }
.mt-player.mt-is-playing .mt-player-status::before { background: var(--rc-red); animation: rc-blink 1.4s ease-in-out infinite; }

/* ---------- Track card ---------- */
.mt-player:not(.moodtube-row-layout) .mt-track-info {
    order: 3; align-items: flex-start; text-align: left;
    background: var(--rc-panel); border-radius: 12px; padding: 8px 30px 8px 12px;
}
.mt-track-title { color: var(--rc-ink); font-size: 14px; font-weight: 600; margin-bottom: 1px; }
.mt-track-subtitle { color: var(--rc-dim); font-size: 11px; font-weight: 400; }
.mt-btn-favorite { color: var(--rc-red); font-size: 13px; right: 10px; top: 9px; }

/* ---------- Buttons ---------- */
.mt-player:not(.moodtube-row-layout) .mt-controls {
    order: 4; width: 100%; box-sizing: border-box; justify-content: center; gap: 7px;
    background: var(--rc-panel); border-radius: 18px; padding: 6px 8px;
}
.mt-controls > .mt-btn {
    width: 32px; height: 32px; box-sizing: border-box;
    display: flex; align-items: center; justify-content: center;
    font-size: 11px; color: var(--rc-ink);
    background: linear-gradient(#fcfcfc, #ebebeb); border: 1px solid var(--rc-edge); border-radius: 50%;
    box-shadow: 0 1px 1px rgba(0, 0, 0, 0.1);
}
.mt-controls > .mt-btn-play {
    width: 42px; height: 42px; font-size: 14px; margin: 0 3px;
    box-shadow: 0 0 0 4px #f6f6f6, 0 0 0 5px var(--rc-edge);
}
.mt-controls > .mt-btn:hover  { transform: none; background: #ffffff; color: var(--rc-ink); }
.mt-controls > .mt-btn:active { background: linear-gradient(#ebebeb, #f6f6f6); }
.mt-btn-ai.mt-is-busy { color: var(--rc-red); }

/* ---------- Volume ---------- */
.mt-player:not(.moodtube-row-layout) .mt-volume { order: 5; width: 100%; padding: 0 2px; box-sizing: border-box; }
.mt-volume-icon { color: var(--rc-dim); font-size: 11px; }
.mt-resize-handle i { color: var(--rc-edge); }

/* ---------- Queue / playlists ---------- */
.mt-panel { background: var(--rc-body); padding-top: 36px; }
.mt-panel-title { color: var(--rc-ink); }
.mt-panel-close, .mt-panel .mt-btn-accent { color: var(--rc-ink); }
.mt-queue-item { background: var(--rc-panel); border-radius: 10px; }
.mt-queue-item:hover { background: #ffffff; }
.mt-queue-item.mt-is-current { background: #ffffff; border-color: var(--rc-ink); }
.mt-queue-thumb { border-radius: 6px; }
.mt-queue-thumb.mt-is-empty { background: var(--rc-edge); }
.mt-queue-title, .mt-queue-item.mt-is-current .mt-queue-title, .mt-playlist-title { color: var(--rc-ink); }
.mt-queue-item.mt-is-blocked .mt-queue-title { color: var(--rc-red); }
.mt-queue-now, .mt-queue-add { color: var(--rc-ink); }
.mt-queue-dislike { background-color: var(--rc-red); }
.mt-queue-empty { color: var(--rc-dim); }

/* ---------- Floating button ---------- */
.mt-fab, .mt-fab.mt-fab-docked {
    background: linear-gradient(#fcfcfc, #e9e9e9); border-color: var(--rc-edge);
    box-shadow: 0 1px 2px rgba(0, 0, 0, 0.18); color: var(--rc-ink);
}
.mt-fab.mt-is-playing .mt-fab-icon { color: var(--rc-red); }

/* ---------- Scrollbars ---------- */
.mt-player *, #mt-settings-modal * { scrollbar-width: thin; scrollbar-color: #bdbdbd var(--rc-panel); }
.mt-player ::-webkit-scrollbar, #mt-settings-modal ::-webkit-scrollbar { width: 8px; height: 8px; }
.mt-player ::-webkit-scrollbar-track, #mt-settings-modal ::-webkit-scrollbar-track { background: var(--rc-panel); border-radius: 4px; }
.mt-player ::-webkit-scrollbar-thumb, #mt-settings-modal ::-webkit-scrollbar-thumb { background: #bdbdbd; border-radius: 4px; }

/* ---------- Settings window ---------- */
#mt-settings-modal, #mt-settings-modal * { text-shadow: none; }
#mt-settings-modal {
    --mt-overlay: rgba(20, 20, 20, 0.35);
    --mt-modal-shadow: none;
    --mt-text-strong: var(--rc-ink);
    --mt-divider: var(--rc-edge);
}
#mt-settings-modal .mt-flex-container { border: 4px solid var(--rc-black); border-radius: 22px; backdrop-filter: none; }
#mt-settings-modal .mt-content { scrollbar-color: #bdbdbd transparent; }
#mt-settings-modal .mt-cat-title:hover { background-color: rgba(0, 0, 0, 0.04); }
#mt-settings-modal .mt-tag { background-color: var(--rc-panel); border-color: var(--rc-edge); box-shadow: none; }
#mt-settings-modal .mt-genre-tag:hover, #mt-settings-modal .mt-mood-tag:hover, #mt-settings-modal .mt-scenario-tag:hover {
    background-color: #ffffff; border-color: var(--rc-ink);
}
#mt-settings-modal .mt-genre-tag.active, #mt-settings-modal .mt-mood-tag.active, #mt-settings-modal .mt-scenario-tag.active {
    background-color: var(--rc-ink); border-color: var(--rc-ink); box-shadow: none;
}
#mt-settings-modal .mt-sum-genre, #mt-settings-modal .mt-sum-mood, #mt-settings-modal .mt-sum-scenario { box-shadow: none; }
#mt-settings-modal .mt-btn-test { background: var(--rc-panel); border-color: var(--rc-edge); }
#mt-settings-modal .mt-btn-test:hover { background: #ffffff; border-color: var(--rc-ink); }
#mt-settings-modal .mt-subpanel { background: var(--rc-panel); }

/* ---------- Search panel and playlists (added to the extension later) ---------- */

.mt-panel-search { --mt-bg-primary: #f1f1f1; }
#moodtube-search-container #moodtube-search-go { color: var(--mt-text-on-accent, #fff) !important; border-radius: 50% !important; }
.mt-player, .mt-pl-modal { --mt-pl-spotify-tab: var(--rc-ink); --mt-pl-spotify-tab-text: #ffffff; }
.mt-btn-favorite.mt-is-active { color: var(--rc-red); }
.mt-pl-tabs { background: var(--rc-panel); border-radius: 999px; }
.mt-pl-tab { color: var(--rc-dim); border-radius: 999px; }
.mt-pl-tool { background: linear-gradient(#fcfcfc, #ebebeb); border-color: var(--rc-edge); color: var(--rc-ink); border-radius: 999px; }
.mt-pl-tool:hover { background: #ffffff; }
.mt-pl-tool.mt-pl-play { background: var(--rc-ink); border-color: var(--rc-ink); color: #ffffff; }
.mt-pl-inline-cancel { background: var(--rc-panel); color: var(--rc-ink); }
.mt-pl-cover-empty { background: var(--rc-panel); color: var(--rc-dim); }
.mt-pl-modal { --mt-overlay: rgba(20, 20, 20, 0.35); }
.mt-pl-modal-box { background: var(--rc-body); border: 4px solid var(--rc-black); border-radius: 22px; box-shadow: none; }
.mt-pl-modal-track { border-bottom-color: var(--rc-edge); }
.mt-pl-option { background: var(--rc-panel); }
.mt-pl-option:hover { background: #ffffff; }
.mt-pl-option.mt-is-added .mt-pl-option-icon { color: var(--rc-ink); }

/* ---------- Theme catalog in the settings window ---------- */
#mt-settings-modal .mt-catalog-preview { background: #dcdcdc; color: var(--rc-dim); }
#mt-settings-modal .mt-catalog-tag { background: var(--rc-panel); color: var(--rc-dim); border-radius: 999px; }

/* ===== Dock bar (strip under the tavern header) [auto] ===== */
#moodtube-dock {
  font-family: 'Inter', 'Segoe UI', sans-serif;
  --mt-dock-cover-radius: 6px;
}
#moodtube-dock, #moodtube-dock * { text-shadow: none; }
#moodtube-dock .mt-dock-cover { border-width: 1.5px; }
#moodtube-dock .mt-dock-controls { gap: 6px; }
#moodtube-dock .mt-dock-btn {
  width: 28px; height: 28px; padding: 0; box-sizing: border-box; line-height: 1; flex-shrink: 0;
  display: flex; align-items: center; justify-content: center; border-radius: 6px;
  font-size: 12px; color: var(--mt-text);
  background: color-mix(in srgb, var(--mt-accent) 12%, transparent);
  transform: none; transition: background-color 0.2s;
}
#moodtube-dock .mt-dock-btn:hover { transform: none; color: var(--mt-text); background: color-mix(in srgb, var(--mt-accent) 28%, transparent); }
#moodtube-dock .mt-dock-play {
  width: 34px; height: 34px; font-size: 14px;
  background: var(--mt-accent); color: var(--mt-text-on-accent, #ffffff);
}
#moodtube-dock .mt-dock-play:hover { background: var(--mt-accent-hover, var(--mt-accent)); color: var(--mt-text-on-accent, #ffffff); }
#moodtube-dock .mt-dock-play.fa-play { padding-left: 2px; }
#moodtube-dock .mt-dock-fav, #moodtube-dock .mt-dock-ai, #moodtube-dock .mt-dock-queue { color: var(--mt-text); }
#moodtube-dock .mt-dock-fav.mt-is-active, #moodtube-dock .mt-dock-ai.mt-is-busy { color: var(--mt-accent); }
#moodtube-dock .mt-dock-expand, #moodtube-dock .mt-dock-close { color: var(--mt-text-dim, var(--mt-text)); }
#moodtube-dock .mt-dock-queue.mt-is-open, #moodtube-dock .mt-dock-expand.mt-is-open {
  color: var(--mt-text); text-shadow: none; background: color-mix(in srgb, var(--mt-accent) 30%, transparent);
}
#moodtube-dock .mt-dock-progress { height: 3px; }
@media (max-width: 420px) {
  #moodtube-dock .mt-dock-inner { gap: 6px; padding-left: 8px; padding-right: 8px; }
  #moodtube-dock .mt-dock-controls { gap: 3px; }
  #moodtube-dock .mt-dock-btn { width: 24px; height: 24px; font-size: 11px; }
  #moodtube-dock .mt-dock-play { width: 28px; height: 28px; font-size: 12px; }
}
